// Main-owned filtered backup. Never reads/pushes raw canonical Git ancestry.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
export const sha=b=>createHash('sha256').update(b).digest('hex');
export const read=p=>fs.readFileSync(p);
export const json=p=>JSON.parse(read(p));
const env={...process.env,GIT_NO_REPLACE_OBJECTS:'1',GIT_TERMINAL_PROMPT:'0'};
export const runGit=(args,input)=>execFileSync('git',args,{env,input,windowsHide:true,maxBuffer:64e6,stdio:['pipe','pipe','pipe']});
const scoped=(repo,args,input)=>runGit(['--git-dir='+repo,...args],input);
const safe=p=>assert(!path.isAbsolute(p)&&!/[\\\x00-\x1f]/.test(p)&&p.split('/').every(v=>v&&v!=='.'&&v!=='..'),'Safe relative source path');
export function backup({root,repo,branch,files,bytesFor,sourceIdentity,scope,proof,verifySource,parent=null,parentRepo=null,parentTree=null,inheritedMetadata=[],carryParent=true}){
 const repository='https://github.com/deliotd-cloud/Visible-medicine.git';assert(!fs.existsSync(root)&&!fs.existsSync(repo));assert(files.length>0&&files.length<6000);assert.equal(new Set(files.map(r=>r.path)).size,files.length);
 for(const row of files){safe(row.path);assert(!row.path.startsWith('.source-backup/'));assert(!/(^|\/)(?:\.env(?:\.[^/]*)?|\.local|\.vinext|node_modules|\.git)(?:\/|$)|\.(?:glb|dcm|dicom|nii(?:\.gz)?|nrrd|sqlite(?:3)?|db)$/i.test(row.path),'Excluded private/runtime/geometry source path');const b=bytesFor(row.path);assert.equal(b.length,row.bytes);assert.equal(sha(b),row.sha256);}
 verifySource();fs.mkdirSync(root,{recursive:true});const state={schema:'vm-filtered-source-backup/2',at:new Date().toISOString(),phase:'selected-source-preflight',repository,branch,parent,sourceIdentity,sourcePaths:files.length,rawCanonicalAncestry:false,wholeProjectBackup:false,privateDataBackup:false,clinicalApproval:false,publicDeployment:false};
 const save=()=>fs.writeFileSync(root+'/state.json',JSON.stringify(state,null,2)+'\n');save();
 assert.equal(runGit(['ls-remote',repository,'refs/heads/'+branch]).toString().trim(),'','Create-only remote branch');runGit(['init','--bare','-q',repo]);
 const git=(args,input)=>scoped(repo,args,input);let previous=[];
 if(parent){assert(parentRepo&&parentTree);assert.equal(scoped(parentRepo,['rev-parse',parent+'^{tree}']).toString().trim(),parentTree);runGit(['--git-dir='+repo,'fetch','--depth=1','--no-tags',parentRepo,parent]);assert.equal(git(['rev-parse','FETCH_HEAD']).toString().trim(),parent);git(['read-tree',parent]);previous=JSON.parse(scoped(parentRepo,['show',parent+':.source-backup/manifest.json'])).files;}
 const prior=new Map(previous.map(r=>[r.path,r])),selected=new Set(files.map(r=>r.path)),delta=files.filter(r=>prior.get(r.path)?.sha256!==r.sha256),removed=previous.filter(r=>!selected.has(r.path));
 const manifest={schema:'vm-source-only-checkpoint/2',at:new Date().toISOString(),sourceIdentity,parent,gitParent:carryParent?parent:null,files,removed:removed.map(r=>r.path),scope,proof,wholeProjectBackup:false,privateDataBackup:false,rawCanonicalAncestry:false,clinicalApproval:false,publicDeployment:false};
 const metadata=[{path:'.source-backup/manifest.json',bytes:Buffer.from(JSON.stringify(manifest,null,2)+'\n')},{path:'.source-backup/README.md',bytes:Buffer.from('# Visible Medicine source-only recovery\n\n'+scope+'\n')},{path:'.source-backup/evidence.json',bytes:Buffer.from(JSON.stringify(proof,null,2)+'\n')}];
 const expected=new Map(files.map(r=>[r.path,r]));for(const r of [...metadata,...inheritedMetadata]){safe(r.path);assert(r.path.startsWith('.source-backup/'));expected.set(r.path,{bytes:r.bytes.length,sha256:sha(r.bytes)});}
 const existingMeta=parent?scoped(parentRepo,['ls-tree','-r','--name-only',parent,'.source-backup']).toString().trim().split('\n').filter(Boolean):[];
 const updates=[...removed.map(r=>'0 '+('0'.repeat(40))+'\t'+r.path+'\0'),...existingMeta.filter(p=>!expected.has(p)).map(p=>'0 '+('0'.repeat(40))+'\t'+p+'\0')];
 for(const r of [...delta.map(r=>({...r,bytes:bytesFor(r.path)})),...metadata,...inheritedMetadata]){const blob=git(['hash-object','-w','--stdin'],r.bytes).toString().trim();updates.push('100644 '+blob+'\t'+r.path+'\0');}
 git(['update-index','-z','--index-info'],Buffer.from(updates.join('')));const tree=git(['write-tree']).toString().trim();const head=runGit(['--git-dir='+repo,'-c','user.name=Visible Medicine source backup','-c','user.email=source-backup@users.noreply.github.com','commit-tree',tree,...(parent&&carryParent?['-p',parent]:[])],Buffer.from('Visible Medicine: verified selected source checkpoint\n')).toString().trim();git(['update-ref','refs/heads/'+branch,head]);
 Object.assign(state,{phase:'local-filtered-commit',head,tree,deltaPaths:delta.length,removedPaths:removed.length,metadataPaths:expected.size-files.length,proof});save();verifySource();console.log(JSON.stringify({phase:state.phase,branch,sourcePaths:files.length,deltaPaths:delta.length,removedPaths:removed.length}));
 git(['push',repository,'refs/heads/'+branch+':refs/heads/'+branch]);assert.equal(runGit(['ls-remote',repository,'refs/heads/'+branch]).toString().trim().split(/\s+/)[0],head);state.phase='pushed-awaiting-independent-readback';save();console.log(JSON.stringify({phase:state.phase,head,tree}));
 const back=root+'/independent-readback.git';runGit(['init','--bare','-q',back]);runGit(['--git-dir='+back,'fetch','--depth=1','--no-tags',repository,'refs/heads/'+branch]);const remote=(args,input)=>scoped(back,args,input);assert.equal(remote(['rev-parse','FETCH_HEAD']).toString().trim(),head);assert.equal(remote(['rev-parse','FETCH_HEAD^{tree}']).toString().trim(),tree);
 const gitParents=remote(['cat-file','-p',head]).toString().split('\n').filter(l=>l.startsWith('parent '));assert.equal(gitParents.length,parent&&carryParent?1:0);state.gitParentAncestryIncluded=gitParents.length>0;
 const entries=remote(['ls-tree','-r','-z',head]).toString().split('\0').filter(Boolean).map(line=>{const[header,p]=line.split('\t'),[mode,type,blob]=header.split(' ');safe(p);assert.equal(mode,'100644');assert.equal(type,'blob');assert(expected.has(p),'Unexpected remote path');return{path:p,blob};});assert.equal(entries.length,expected.size);
 for(let i=0;i<entries.length;i+=24){const batch=entries.slice(i,i+24),output=remote(['cat-file','--batch'],Buffer.from(batch.map(r=>r.blob).join('\n')+'\n'));let cursor=0;for(const r of batch){const end=output.indexOf(10,cursor);assert(end>cursor);const[blob,type,size]=output.subarray(cursor,end).toString().split(' ');assert.equal(blob,r.blob);assert.equal(type,'blob');cursor=end+1;const b=output.subarray(cursor,cursor+Number(size));cursor+=Number(size);assert.equal(output[cursor++],10);const expectedRow=expected.get(r.path);assert.equal(b.length,expectedRow.bytes,r.path);assert.equal(sha(b),expectedRow.sha256,r.path);const p=path.resolve(root,'remote-source-restored',r.path);assert(p.startsWith(path.resolve(root,'remote-source-restored')+path.sep));fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,b,{flag:'wx'});}assert.equal(cursor,output.length);}
 remote(['fsck','--strict','--no-reflogs']);verifySource();Object.assign(state,{at:new Date().toISOString(),phase:'independent-fetch-tree-bytes-and-restore-verified',sourceBackupVerified:true,strictIntegrity:true,restoredPaths:entries.length});save();fs.writeFileSync(root+'/github-backup.json',JSON.stringify(state,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({receipt:root+'/github-backup.json',sha256:sha(read(root+'/github-backup.json')),head,tree,restoredPaths:entries.length}));return state;
}
